-- Product and category text in the six languages besides English.
-- English stays in title / description / name; the other languages live here:
--   products.translations   = { "ar": { "title": "...", "description": "..." }, "zh": {...}, ... }
--   categories.translations = { "ar": "...", "zh": "...", ... }
-- The storefront falls back to English when a language is missing, and keeps working before this runs.

alter table public.products   add column if not exists translations jsonb not null default '{}'::jsonb;
alter table public.categories add column if not exists translations jsonb not null default '{}'::jsonb;

-- Seed products from the first version of the site (matched by their original drawing).
update public.products set translations = '{"zh":{"title":"铬银泡泡羽绒服","description":"液态银色尼龙短款羽绒服，超大绗缝格与高防风立领。"},"hi":{"title":"क्रोम बबल पफ़र","description":"लिक्विड-सिल्वर नायलॉन से बनी क्रॉप्ड पफ़र जैकेट, बड़े क्विल्टेड पैनल और ऊँचे स्टॉर्म कॉलर के साथ।"},"es":{"title":"Plumífero burbuja cromado","description":"Plumífero corto de nailon plateado líquido, con acolchado XL y cuello alto cortavientos."},"fr":{"title":"Doudoune bulle chromée","description":"Doudoune courte en nylon argent liquide, à larges compartiments et col montant coupe-vent."},"ar":{"title":"سترة منفوخة كرومية","description":"سترة منفوخة قصيرة من النايلون الفضي اللامع، بحشوات كبيرة وياقة عالية واقية من الرياح."},"bn":{"title":"ক্রোম বাবল পাফার","description":"তরল-রুপালি নাইলনের ক্রপড পাফার জ্যাকেট, বড় কুইল্টেড প্যানেল আর উঁচু স্টর্ম কলার সহ।"}}'::jsonb
  where images[1] = '/legacy/products/p01.svg' and translations = '{}'::jsonb;
update public.products set translations = '{"zh":{"title":"全息赛车夹克","description":"全息人造皮革宽松机车夹克，配撞色滚边与双向拉链。"},"hi":{"title":"होलो रेसर जैकेट","description":"होलोग्राफ़िक फ़ॉक्स लेदर की बॉक्सी मोटो जैकेट, कंट्रास्ट पाइपिंग और टू-वे ज़िप के साथ।"},"es":{"title":"Chaqueta racer holográfica","description":"Chaqueta motera amplia de piel sintética holográfica, con vivos en contraste y cremallera doble."},"fr":{"title":"Veste racer holographique","description":"Veste motarde ample en similicuir holographique, passepoils contrastés et zip double sens."},"ar":{"title":"جاكيت سباق هولوغرامي","description":"جاكيت دراجات واسع من الجلد الصناعي الهولوغرامي، بحواف متباينة وسحاب باتجاهين."},"bn":{"title":"হোলো রেসার জ্যাকেট","description":"হলোগ্রাফিক ফক্স লেদারের বক্সি মোটো জ্যাকেট, কনট্রাস্ট পাইপিং আর টু-ওয়ে জিপ সহ।"}}'::jsonb
  where images[1] = '/legacy/products/p02.svg' and translations = '{}'::jsonb;
update public.products set translations = '{"zh":{"title":"幻彩防风外套","description":"轻若无物的外壳，色泽在冰蓝与紫罗兰之间流转，兜帽可收纳。"},"hi":{"title":"इंद्रधनुषी विंडब्रेकर","description":"बेहद हल्की शेल जैकेट जो आइस-ब्लू से बैंगनी रंग में बदलती है, फ़ोल्ड होने वाले हुड के साथ।"},"es":{"title":"Cortavientos iridiscente","description":"Una capa ultraligera que cambia de azul hielo a violeta, con capucha plegable."},"fr":{"title":"Coupe-vent irisé","description":"Une coque ultralégère aux reflets bleu glacier à violet, avec capuche escamotable."},"ar":{"title":"سترة واقية من الرياح متقزحة","description":"سترة خفيفة جدًا يتبدّل لونها من الأزرق الجليدي إلى البنفسجي، بغطاء رأس قابل للطي."},"bn":{"title":"রংবদলানো উইন্ডব্রেকার","description":"পালকের মতো হালকা শেল জ্যাকেট, রং বদলায় বরফ-নীল থেকে বেগুনিতে, ভাঁজ করা যায় এমন হুড সহ।"}}'::jsonb
  where images[1] = '/legacy/products/p03.svg' and translations = '{}'::jsonb;
update public.products set translations = '{"zh":{"title":"赛博人造毛大衣","description":"及膝长款银尖人造毛大衣，缎面内衬，暗扣设计。"},"hi":{"title":"फ़ॉक्स-फ़र साइबर कोट","description":"सिल्वर-टिप वाले फ़ॉक्स फ़र का घुटने तक लंबा कोट, सैटिन लाइनिंग और छिपे हुए स्नैप बटन के साथ।"},"es":{"title":"Abrigo cyber de pelo sintético","description":"Abrigo hasta la rodilla de pelo sintético con puntas plateadas, forro de satén y broches ocultos."},"fr":{"title":"Manteau cyber en fausse fourrure","description":"Manteau mi-long en fausse fourrure aux pointes argentées, doublure satinée et pressions cachées."},"ar":{"title":"معطف سايبر من الفرو الصناعي","description":"معطف بطول الركبة من الفرو الصناعي بأطراف فضية، مع بطانة ساتان وأزرار كبس مخفية."},"bn":{"title":"ফক্স-ফার সাইবার কোট","description":"রুপালি ডগার ফক্স ফারের হাঁটু-লম্বা কোট, স্যাটিন লাইনিং আর লুকানো স্ন্যাপ বোতাম সহ।"}}'::jsonb
  where images[1] = '/legacy/products/p04.svg' and translations = '{}'::jsonb;
update public.products set translations = '{"zh":{"title":"网眼机能马甲","description":"机能网眼叠穿马甲，六个工装口袋，侧边绑带可调节。"},"hi":{"title":"मेश यूटिलिटी वेस्ट","description":"टेक्निकल मेश की लेयरिंग वेस्ट, छह कार्गो पॉकेट और एडजस्ट होने वाली साइड स्ट्रैप के साथ।"},"es":{"title":"Chaleco utilitario de malla","description":"Chaleco de malla técnica para superponer, con seis bolsillos cargo y tiras laterales ajustables."},"fr":{"title":"Gilet utilitaire en mesh","description":"Gilet en mesh technique à superposer, six poches cargo et sangles latérales réglables."},"ar":{"title":"صديري عملي شبكي","description":"صديري من القماش الشبكي التقني للارتداء فوق الملابس، بستة جيوب كارغو وأحزمة جانبية قابلة للتعديل."},"bn":{"title":"মেশ ইউটিলিটি ভেস্ট","description":"টেকনিক্যাল মেশের লেয়ারিং ভেস্ট, ছয়টি কার্গো পকেট আর অ্যাডজাস্টেবল সাইড স্ট্র্যাপ সহ।"}}'::jsonb
  where images[1] = '/legacy/products/p05.svg' and translations = '{}'::jsonb;
update public.products set translations = '{"zh":{"title":"部落火焰短款T恤","description":"修身短款罗纹T恤，胸前印有铬银部落火焰图案。"},"hi":{"title":"ट्राइबल फ़्लेम बेबी टी","description":"छोटी फ़िटेड रिब टी-शर्ट, छाती पर क्रोम ट्राइबल फ़्लेम प्रिंट के साथ।"},"es":{"title":"Baby tee llamas tribales","description":"Camiseta corta de canalé ajustada con estampado de llamas tribales cromadas en el pecho."},"fr":{"title":"Baby tee flammes tribales","description":"T-shirt court et ajusté en maille côtelée, imprimé flammes tribales chromées sur la poitrine."},"ar":{"title":"تيشيرت قصير بلهب قبلي","description":"تيشيرت قصير ضيق من القماش المضلّع، بطبعة لهب قبلية كرومية على الصدر."},"bn":{"title":"ট্রাইবাল ফ্লেম বেবি টি","description":"ছোট ফিটেড রিব টি-শার্ট, বুকে ক্রোম ট্রাইবাল আগুনের প্রিন্ট সহ।"}}'::jsonb
  where images[1] = '/legacy/products/p06.svg' and translations = '{}'::jsonb;
update public.products set translations = '{"zh":{"title":"金属光泽挂脖上衣","description":"液态金属箔挂脖上衣，系带领口，露背设计，长度及腰。"},"hi":{"title":"मेटैलिक हॉल्टर टॉप","description":"लिक्विड-फ़ॉइल हॉल्टर टॉप, टाई वाली गर्दन और खुली पीठ के साथ, कमर तक की लंबाई।"},"es":{"title":"Top halter metalizado","description":"Top halter de foil líquido con lazada al cuello y espalda abierta, a la altura de la cintura."},"fr":{"title":"Top dos nu métallisé","description":"Top dos nu en foil liquide, lien à nouer au cou, coupé pour s''arrêter à la taille."},"ar":{"title":"توب معدني بربطة رقبة","description":"توب لامع كالمعدن السائل يُربط حول الرقبة بظهر مكشوف، بطول يصل إلى الخصر."},"bn":{"title":"মেটালিক হল্টার টপ","description":"তরল-ফয়েলের হল্টার টপ, গলায় বাঁধার ফিতা আর খোলা পিঠ সহ, কোমর পর্যন্ত কাট।"}}'::jsonb
