update public.products set translations = '{"zh":{"title":"印花网纱打底上衣","description":"印花弹力网纱透视长袖上衣，适合叠穿在背心或文胸外。"},"hi":{"title":"मेश लेयर टॉप","description":"प्रिंटेड पावर मेश का पारदर्शी लॉन्ग-स्लीव टॉप, टैंक या ब्रालेट के ऊपर पहनने के लिए।"},"es":{"title":"Top de malla para capas","description":"Top transparente de manga larga en malla elástica estampada, para llevar sobre una camiseta o bralette."},"fr":{"title":"Top en mesh à superposer","description":"Top transparent à manches longues en mesh imprimé, à porter sur un débardeur ou une brassière."},"ar":{"title":"توب شبكي للطبقات","description":"توب شفاف بأكمام طويلة من القماش الشبكي المطاطي المطبوع، يُلبس فوق قميص داخلي أو حمالة صدر."},"bn":{"title":"মেশ লেয়ার টপ","description":"প্রিন্টেড পাওয়ার মেশের স্বচ্ছ লং-স্লিভ টপ, ট্যাঙ্ক বা ব্রালেটের ওপরে পরার জন্য।"}}'::jsonb
