update public.products set translations = '{"zh":{"title":"铬银条纹运动裤","description":"宽松经编运动裤，侧边反光铬银条纹，裤脚按扣开合。"},"hi":{"title":"क्रोम स्ट्राइप ट्रैक पैंट","description":"ट्राइकॉट की आरामदायक ट्रैक पैंट, किनारों पर रिफ़्लेक्टिव क्रोम धारियाँ और स्नैप हेम के साथ।"},"es":{"title":"Pantalón de chándal con franja cromada","description":"Pantalón de chándal holgado de tricot con franjas laterales cromadas reflectantes y bajos con broches."},"fr":{"title":"Pantalon de survêtement à bande chromée","description":"Pantalon de survêtement ample en tricot, bandes latérales chromées réfléchissantes et bas à pressions."},"ar":{"title":"بنطال رياضي بشريط كرومي","description":"بنطال رياضي مريح من التريكو، بشرائط جانبية كرومية عاكسة وأطراف بأزرار كبس."},"bn":{"title":"ক্রোম স্ট্রাইপ ট্র্যাক প্যান্ট","description":"ট্রাইকটের আরামদায়ক ট্র্যাক প্যান্ট, পাশে প্রতিফলিত ক্রোম ডোরা আর স্ন্যাপ হেম সহ।"}}'::jsonb
