update public.products set translations = '{"zh":{"title":"宽松木匠短裤","description":"及膝帆布短裤，带锤环与工具口袋，水洗石墨色。"},"hi":{"title":"बैगी कारपेंटर शॉर्ट्स","description":"घुटने तक के कैनवास शॉर्ट्स, हैमर लूप, टूल पॉकेट और धुले हुए ग्रेफ़ाइट रंग के साथ।"},"es":{"title":"Bermudas carpintero holgadas","description":"Bermudas de lona hasta la rodilla con trabilla de martillo, bolsillos de herramientas y tono grafito lavado."},"fr":{"title":"Short charpentier ample","description":"Short en toile au genou, passant à marteau, poches à outils et teinte graphite délavée."},"ar":{"title":"شورت نجّار واسع","description":"شورت من قماش الكانفاس بطول الركبة، بحلقة مطرقة وجيوب للأدوات ولون غرافيتي مغسول."},"bn":{"title":"ব্যাগি কার্পেন্টার শর্টস","description":"হাঁটু পর্যন্ত ক্যানভাস শর্টস, হ্যামার লুপ, টুল পকেট আর ধোয়া গ্রাফাইট রঙ সহ।"}}'::jsonb
